20	/**
21	 * Parses custom ID from a heading. The ID can contain any characters except
22	 * `{#` and `}`.
23	 *
24	 * @param heading e.g. `## Some heading {#some-heading}` where the last
25	 * character must be `}` for the ID to be recognized
26	 */
27	export function parseMarkdownHeadingId(heading: string): {
28	  /**
29	   * The heading content sans the ID part, right-trimmed. e.g. `## Some heading`
30	   */
31	  text: string;
32	  /** The heading ID. e.g. `some-heading` */
33	  id: string | undefined;
34	} {
35	  const customHeadingIdRegex = /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/;
36	  const matches = customHeadingIdRegex.exec(heading);
37	  if (matches) {
38	    return {
39	      text: heading.replace(matches[0]!, ''),
40	      id: matches.groups!.id!,
41	    };
42	  }
43	  return {text: heading, id: undefined};
44	}
