418	/**
419	 * Takes Markdown content, returns new content with heading IDs written.
420	 * Respects existing IDs (unless `overwrite=true`) and never generates colliding
421	 * IDs (through the slugger).
422	 */
423	export function writeMarkdownHeadingId(
424	  content: string,
425	  options: WriteHeadingIDOptions = {maintainCase: false, overwrite: false},
426	): string {
427	  const {maintainCase = false, overwrite = false} = options;
428	  const lines = content.split('\n');
429	  const slugger = createSlugger();
430	
431	  // If we can't overwrite existing slugs, make sure other headings don't
432	  // generate colliding slugs by first marking these slugs as occupied
433	  if (!overwrite) {
434	    lines.forEach((line) => {
435	      const parsedHeading = parseMarkdownHeadingId(line);
436	      if (parsedHeading.id) {
437	        slugger.slug(parsedHeading.id);
438	      }
439	    });
440	  }
441	
442	  let inCode = false;
443	  return lines
444	    .map((line) => {
445	      if (line.startsWith('```')) {
446	        inCode = !inCode;
447	        return line;
448	      }
449	      // Ignore h1 headings, as we don't create anchor links for those
450	      if (inCode || !line.startsWith('##')) {
451	        return line;
452	      }
453	      const parsedHeading = parseMarkdownHeadingId(line);
454	
455	      // Do not process if id is already there
456	      if (parsedHeading.id && !overwrite) {
457	        return line;
458	      }
459	      return addHeadingId(parsedHeading.text, slugger, maintainCase);
460	    })
461	    .join('\n');
462	}
