8	import GithubSlugger from 'github-slugger';
9	
10	// We create our own abstraction on top of the lib:
11	// - unify usage everywhere in the codebase
12	// - ability to add extra options
13	export type SluggerOptions = {
14	  /** Keep the headings' casing, otherwise make all lowercase. */
15	  maintainCase?: boolean;
16	};
17	
18	export type Slugger = {
19	  /**
20	   * Takes a Markdown heading like "Josh Cena" and sluggifies it according to
21	   * GitHub semantics (in this case `josh-cena`). Stateful, because if you try
22	   * to sluggify "Josh Cena" again it would return `josh-cena-1`.
23	   */
24	  slug: (value: string, options?: SluggerOptions) => string;
25	};
26	
27	/**
28	 * A thin wrapper around github-slugger. This is a factory function that returns
29	 * a stateful Slugger object.
30	 */
31	export function createSlugger(): Slugger {
32	  const githubSlugger = new GithubSlugger();
33	  return {
34	    slug: (value, options) => githubSlugger.slug(value, options?.maintainCase),
35	  };
36	}
